const tickets = $input.all();

// ========================================
// HANDLE NO PREVIOUS TICKETS
// ========================================

if (tickets.length === 0) {
  return [
    {
      json: {
        total_previous_tickets: 0,
        open_ticket_count: 0,
        repeated_issue_count: 0,
        previous_issue_summary: "No previous IT tickets found for this employee.",
        previous_resolution: "No previous resolution available.",
        previous_ticket_context: "This employee has no recorded IT incident history."
      }
    }
  ];
}


// ========================================
// COUNT OPEN TICKETS
// ========================================

const openTickets = tickets.filter(ticket => {
  const status = String(ticket.json.status || "").toLowerCase();

  return status === "open" ||
         status === "in progress" ||
         status === "pending";
});


// ========================================
// PREPARE PREVIOUS ISSUES
// ========================================

const previousIssues = tickets
  .map(ticket => ticket.json.issue_subject)
  .filter(Boolean);


// ========================================
// PREPARE PREVIOUS RESOLUTIONS
// ========================================

const previousResolutions = tickets
  .map(ticket => ticket.json.resolution)
  .filter(Boolean);


// ========================================
// DETECT REPEATED ISSUES
// ========================================

const issueCounts = {};

previousIssues.forEach(issue => {
  const key = issue.toLowerCase().trim();

  issueCounts[key] = (issueCounts[key] || 0) + 1;
});

const repeatedIssues = Object.entries(issueCounts)
  .filter(([issue, count]) => count > 1)
  .map(([issue, count]) => ({
    issue,
    count
  }));


// ========================================
// CREATE AI CONTEXT
// ========================================

const previousTicketContext = tickets
  .map(ticket => {
    const t = ticket.json;

    return `
Ticket ID: ${t.ticket_id || "Unknown"}
Issue: ${t.issue_subject || "Not available"}
Description: ${t.issue_description || "Not available"}
Category: ${t.category || "Not available"}
Priority: ${t.priority || "Not available"}
Status: ${t.status || "Not available"}
Resolution: ${t.resolution || "Not available"}
`;
  })
  .join("\n------------------------\n");


// ========================================
// FINAL OUTPUT
// ========================================

return [
  {
    json: {
      total_previous_tickets: tickets.length,

      open_ticket_count: openTickets.length,

      previous_issue_summary:
        previousIssues.length > 0
          ? previousIssues.join(" | ")
          : "No previous issues found.",

      previous_resolution:
        previousResolutions.length > 0
          ? previousResolutions.join(" | ")
          : "No previous resolutions found.",

      repeated_issue_count: repeatedIssues.length,

      repeated_issues: repeatedIssues,

      previous_ticket_context: previousTicketContext
    }
  }
];

