const incidents = $input.all();

// ========================================
// HANDLE NO SIMILAR INCIDENTS
// ========================================

if (incidents.length === 0) {
  return [
    {
      json: {
        total_similar_incidents: 0,
        open_similar_incidents: 0,
        resolved_similar_incidents: 0,
        common_categories: [],
        previous_root_causes: [],
        successful_resolutions: [],
        incident_history_context: "No similar previous incidents were found."
      }
    }
  ];
}


// ========================================
// COUNT INCIDENT STATUS
// ========================================

const openStatuses = ["open", "in progress", "pending", "escalated"];

const openIncidents = incidents.filter((item) => {
  const status = String(item.json.status || "").trim().toLowerCase();

  return openStatuses.includes(status);
});

const resolvedIncidents = incidents.filter((item) => {
  const status = String(item.json.status || "").trim().toLowerCase();

  return status === "resolved" || status === "closed";
});


// ========================================
// GET UNIQUE VALUES
// ========================================

function getUniqueValues(fieldName) {
  return [
    ...new Set(
      incidents
        .map((item) => item.json[fieldName])
        .filter(
          (value) =>
            value !== undefined &&
            value !== null &&
            String(value).trim() !== ""
        )
        .map((value) => String(value).trim())
    )
  ];
}


// ========================================
// EXTRACT IMPORTANT INCIDENT DATA
// ========================================

const categories = getUniqueValues("category");

const rootCauses = getUniqueValues("root_cause");

const resolutions = getUniqueValues("resolution");


// ========================================
// CREATE DETAILED INCIDENT HISTORY
// ========================================

const incidentHistoryContext = incidents
  .map((item, index) => {
    const incident = item.json;

    return `
SIMILAR INCIDENT ${index + 1}

Ticket ID: ${incident.ticket_id || "Not available"}
Employee: ${incident.employee_name || "Not available"}
Issue Subject: ${incident.issue_subject || "Not available"}
Issue Description: ${incident.issue_description || "Not available"}
Category: ${incident.category || "Not available"}
Subcategory: ${incident.subcategory || "Not available"}
Priority: ${incident.priority || "Not available"}
Status: ${incident.status || "Not available"}
Root Cause: ${incident.root_cause || "Not available"}
Resolution: ${incident.resolution || "Not available"}
Created At: ${incident.created_at || "Not available"}
Resolved At: ${incident.resolved_at || "Not available"}
`;
  })
  .join("\n----------------------------------------\n");


// ========================================
// FINAL OUTPUT
// ========================================

return [
  {
    json: {
      total_similar_incidents: incidents.length,

      open_similar_incidents: openIncidents.length,

      resolved_similar_incidents: resolvedIncidents.length,

      common_categories: categories,

      previous_root_causes:
        rootCauses.length > 0
          ? rootCauses
          : ["No previous root cause recorded"],

      successful_resolutions:
        resolutions.length > 0
          ? resolutions
          : ["No previous resolution recorded"],

      incident_history_context: incidentHistoryContext
    }
  }
];

