const priorityData = $json.output;

const priority = String(priorityData.priority || "Low").trim();

const slaMap = {
  Critical: 1,
  High: 4,
  Medium: 8,
  Low: 24,
};

const slaHours = slaMap[priority] || 24;

const now = new Date();

const deadline = new Date(
  now.getTime() + slaHours * 60 * 60 * 1000
);

return [
  {
    json: {
      ...priorityData,
      sla_deadline: deadline.toISOString(),
      sla_status: "Active"
    }
  }
];

